#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("用法：本程序 一个整数\n");
        printf("（本喵空着手来的，先退场了）\n");
    } else {
        int n = atoi(argv[1]);
        printf("%d 翻倍是 %d\n", n, n * 2);
    }

    printf("--- 下面这趟是本喵自己捏的一串投喂 ---\n");
    char *demo[2] = {"benmiao", "{a}"};
    int n = atoi(demo[1]);
    printf("%d 翻倍是 %d\n", n, n * 2);
    return 0;
}
